    const loadMe = vi.fn()
    const result = await authorizeNavigation(
      { fullPath: '/workflows', meta: { auth: true } },
      authState(null),
      loadMe,
    )
    expect(result).toEqual({ path: '/login', query: { next: '/workflows' } })
    expect(loadMe).not.toHaveBeenCalled()
  })

